function activeRecall(agentName, task) {
  const ERROR_LOG = path.join("agents", "evaluator", "ERROR_LOG.jsonl");
  if (!agentName || !fs.existsSync(ERROR_LOG)) {
    return { triggered: false, warnings: [] };
